const FormData = require('form-data');
const fs = require('fs');
const https = require('https');

const baseURL = 'https://api.natif.ai';
const workflow = '<API_HANDLE>'; // TODO: Insert or load your API-handle here
const apiKey = '<API_KEY>'; // TODO: Insert or load your API-key secret here
const filePath = '<FILE_PATH>'; // TODO: Insert or load your file path here
const lang = 'de';

const sendNatifRequest = (URL, filePath) => {
  const formData = new FormData();
  formData.append('file', fs.createReadStream(filePath));
  formData.append('parameters', `{"language": "${lang}"}`);

  const headers = {
    Accept: 'application/json',
    Authorization: `ApiKey ${apiKey}`,
    'content-type': formData.getHeaders()['content-type'],
  };

  const options = {
    method: 'POST',
    headers,
  };
  const request = https.request(URL, options);

  formData.pipe(request)

  request.on('error', error => {
    console.error(error);
  });

  request.on('response', response => {
    body = '';
    response.on('data', chunk => {
      body += chunk;
    });
    response.on('end', () => {
      // "vendor name" is chosen as an example field for this extraction and can be replaced with custom fields
      const vendorName = JSON.parse(body).extractions.vendor.name;
      if (vendorName) {
        console.log(`Vendor name: ${vendorName.value}`);
        console.log(`Vendor name confidence: ${vendorName.confidence}`);
      } else {
        console.log('Vendor name could not be extracted');
      }      
    });
  });
}

