package com.natif;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLConnection;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.UUID;
import com.google.gson.*;

public class TrainYourOwnExtraction {
    private static final String baseURL = "https://api.natif.ai";
    private static final String workflow = "<API_HANDLE>"; // TODO: Insert or load your API-handle here
    private static final String apiKey = "<API_KEY>"; // TODO: Insert or load your API-key secret here
    private static final String filePath = "<FILE_PATH>"; // TODO: Insert or load your file path here
    private static final String lang = "de";

    private static final String EOL = "\r\n";

    private static String sendNatifRequest(String filePath, String workflow, ArrayList<String> params ) throws IOException {
        String queryParams = String.join("&", params);
        String responseString = "";
        try (FileInputStream file = new FileInputStream(filePath)) {
            String urlBase = baseURL + "/processing/%s?%s";
            HttpURLConnection con = (HttpURLConnection) new URL(String.format(urlBase, workflow, queryParams))
                    .openConnection();
            final String boundary = UUID.randomUUID().toString();
            con.setDoOutput(true);
            con.setRequestMethod("POST");
            con.setRequestProperty("Content-Type", "multipart/form-data; boundary=" + boundary);
            con.setRequestProperty("Accept", "application/json");
            con.setRequestProperty("Authorization", "ApiKey " + apiKey);
            try (OutputStream out = con.getOutputStream()) {
                out.write(("--" + boundary + EOL +
                        "Content-Disposition: form-data; name=\"file\"; " +
                        "filename=\"" + filePath + "\"" + EOL +
                        "Content-Type: " + URLConnection.guessContentTypeFromName(filePath) + EOL + EOL)
                        .getBytes(StandardCharsets.UTF_8));
                byte[] buffer = new byte[128];
                int size = -1;
                while (-1 != (size = file.read(buffer))) {
                    out.write(buffer, 0, size);
                }
                out.write((EOL + "--" + boundary + EOL +
                        "Content-Disposition: form-data; name=\"parameters\" " + EOL + EOL +
                        "{\"language\": \"" + lang + "\"}")
                        .getBytes(StandardCharsets.UTF_8));
                out.write((EOL + "--" + boundary + "--" + EOL).getBytes(StandardCharsets.UTF_8));
                out.flush();
                InputStream inputStream = con.getInputStream();
                BufferedReader bufferedReader = new BufferedReader(
                        new InputStreamReader(inputStream));
                StringBuilder response = new StringBuilder();
                String currentLine;

                while ((currentLine = bufferedReader.readLine()) != null)
                    response.append(currentLine);
                responseString = response.toString();
                bufferedReader.close();
            } finally {
                con.disconnect();
            }
            return responseString;
        }
    }

    public static void main(String[] args) throws IOException {
        ArrayList<String> params = new ArrayList<String>();
        params.add("include=extractions");
        params.add("include=ocr");
        String responseString = sendNatifRequest(filePath, workflow, params);
        Gson gson = new Gson();
        JsonObject responseJson = gson.fromJson(responseString, JsonObject.class);

        JsonObject extractions = responseJson.getAsJsonObject("extractions");

        // "vendor name" is chosen as an example field for this extraction and can be replaced with custom fields
        JsonObject vendor = extractions.getAsJsonObject("vendor");
        JsonElement vendorElement = vendor.get("name");
        if (!(vendorElement instanceof JsonNull)) {
            String name = vendor.getAsJsonObject("name").get("value").getAsString();
            System.out.printf("Vendor name: %s\n", name);
            String confidence = vendor.getAsJsonObject("name").get("confidence").getAsString();
            System.out.printf("Vendor name confidence: %s\n", confidence);
        } else {
            System.out.println("Vendor name could not be extracted");
        }        
    }
}

using Newtonsoft.Json.Linq;

using (HttpClient httpClient = new HttpClient())
{
    string baseURL = "https://api.natif.ai";
    string workflow = "<API_HANDLE>";    // TODO: Insert or load your API-handle here
    string apiKey = "<API_KEY>";    // TODO: Insert or load your API-key secret here
    string filePath = "<FILE_PATH>";    // TODO: Insert or load your file path here
    string lang = "de";

    string[] queryParams = { "include=extractions", "include=ocr" };
    string queryString = String.Join("&", queryParams);
    string query = baseURL + "/processing/" + workflow + "?" + queryString;

    using (HttpRequestMessage request = new HttpRequestMessage(new HttpMethod("POST"), query))
    {
        request.Headers.TryAddWithoutValidation("accept", "application/json");
        request.Headers.TryAddWithoutValidation("Authorization", "ApiKey " + apiKey);

        MultipartFormDataContent multipartContent = new MultipartFormDataContent();
        ByteArrayContent file1 = new ByteArrayContent(File.ReadAllBytes(filePath));
        multipartContent.Add(file1, "file", Path.GetFileName(filePath));
        multipartContent.Add(new StringContent("{\"language\": \"" + lang + "\"}"), "parameters");
        request.Content = multipartContent;

        HttpResponseMessage response = await httpClient.SendAsync(request);

        string responseString = await response.Content.ReadAsStringAsync();

        try
        {
            // "vendor name" is chosen as an example field for this extraction and can be replaced with custom fields
            JObject responseJson = JObject.Parse(responseString);
            if ((responseJson["extractions"]["vendor"]["name"]).Type != JTokenType.Null)
            {
                JToken vendorName = responseJson["extractions"]["vendor"]["name"];
                Console.WriteLine("Vendor name: " + vendorName["value"].ToString());
                Console.WriteLine("Vendor name confidence: " + vendorName["confidence"].ToString());
            }
            else
            {
                Console.WriteLine("Vendor name could not be extracted");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(responseString);
            Console.WriteLine(ex.Message);
            throw;
        }        
    }
}
